#include <Arduino.h>

String line;

void applyColors(const String &s) {
  digitalWrite(4, s.indexOf("Red") >= 0 ? LOW : HIGH);
  digitalWrite(3, s.indexOf("Green") >= 0 ? LOW : HIGH);
  digitalWrite(2, s.indexOf("Blue") >= 0 ? LOW : HIGH);
}

void setup() {
  digitalWrite(4, HIGH);
  digitalWrite(3, HIGH);
  digitalWrite(2, HIGH);
  pinMode(4, OUTPUT);
  pinMode(3, OUTPUT);
  pinMode(2, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    if (c == '\n') {
      applyColors(line);
      line = "";
    } else {
      line += c;
    }
  }
}
